import{_ as a,o as t,c as i,a2 as l}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"6.1 多设备同步与切换","description":"同一套任务和产物在不同设备上保持一致。","frontmatter":{"title":"6.1 多设备同步与切换","description":"同一套任务和产物在不同设备上保持一致。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-6/6-1.md","filePath":"delivery/stage-6/6-1.md","lastUpdated":1793859143000}'),r={name:"delivery/stage-6/6-1.md"};function o(n,e,s,d,_,c){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="_6-1-多设备同步与切换" tabindex="-1">6.1 多设备同步与切换 <a class="header-anchor" href="#_6-1-多设备同步与切换" aria-label="Permalink to &quot;6.1 多设备同步与切换&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>让用户在电脑、手机和其他设备上看到同一套任务、产物和记忆，切换设备时不丢任务，也不会出现两个互相矛盾的 Agent。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>为每台设备建立独立身份，用户能查看、命名和移除设备。</li><li>任务、产物和记忆的变化按时间同步，设备重新上线后只补缺失部分。</li><li>发生冲突时保留两边记录，按明确规则合并，无法判断时交给用户。</li><li>同一时间只有一个设备负责执行同一个任务，避免重复操作。</li><li>断网时允许排队，恢复后继续；已经执行过的外部操作不能再次执行。</li><li>用两台真实设备验证：切换后状态一致，任务不丢，产物可打开。</li></ol>',5)])])}const m=a(r,[["render",o]]);export{p as __pageData,m as default};
